'use strict';
const { Model } = require('sequelize');

module.exports = (sequelize, DataTypes) => {
  class User extends Model {
    static associate(models) {
      // Các quan hệ với bảng khác sẽ khai báo ở đây
    }
  }

  User.init({
    UserName: {
      type: DataTypes.STRING,
      allowNull: false
    },
    UserPassword: {
      type: DataTypes.STRING,
      allowNull: false
    },
    Email: {
      type: DataTypes.STRING,
      allowNull: false,
      unique: true
    },
    Phone: {
      type: DataTypes.STRING
    },
    Role: {
      type: DataTypes.STRING,
      allowNull: false,
      defaultValue: 'user' // Mặc định là user
    }
  }, {
    sequelize,
    modelName: 'User',
    tableName: 'Users', // Tên bảng trong DB
    timestamps: false // Nếu không cần createdAt, updatedAt
  });

  return User;
};

