sourcesContent:
'use strict';
const { Model } = require('sequelize');

module.exports = (sequelize, DataTypes) => {
  class Tour extends Model {
    static associate(models) {
      // Liên kết với bảng Detail, Book_Tour
      Tour.hasMany(models.Detail, { foreignKey: "TourId", onDelete: "CASCADE" });
      Tour.hasMany(models.Book_Tour, { foreignKey: "TourId", onDelete: "CASCADE" });
    }
  }

  Tour.init({
    TourId: {
      allowNull: false,
      autoIncrement: true,
      primaryKey: true,
      type: DataTypes.INTEGER
    },
    TourName: {
      type: DataTypes.STRING,
      allowNull: false
    },
    CategoryName: {
      type: DataTypes.STRING
    },
    TourLocation: {
      type: DataTypes.STRING
    },
    TourTime: {
      type: DataTypes.INTEGER
    },
    TourPrice: {
      type: DataTypes.FLOAT,
      defaultValue: 0
    },
    TourDifficulty: {
      type: DataTypes.STRING,
      defaultValue: 'Easy',
      validate: {
        isIn: [['Easy', 'Medium', 'High']]
      }
    },
    TourMinAge: {
      type: DataTypes.INTEGER
    },
    DescribeTour: {
      type: DataTypes.TEXT
    }
  }, {
    sequelize,
    modelName: 'Tour',
    tableName: 'Tours', // Tên bảng trong DB
    timestamps: true // Nếu không cần createdAt, updatedAt
  });

  return Tour;
};

