sourcesContent:
'use strict';
const { Model } = require('sequelize');

module.exports = (sequelize, DataTypes) => {
    class Payment extends Model {
        static associate(models) {
            Payment.belongsTo(models.Book_Tour, { foreignKey: "BookTourId", onDelete: "CASCADE" });
            Payment.belongsTo(models.User, { foreignKey: "UserId", onDelete: "CASCADE" });
        }
    }

    Payment.init({
        PaymentId: {
            allowNull: false,
            autoIncrement: true,
            primaryKey: true,
            type: DataTypes.INTEGER
        },
        BookTourId: {
            type: DataTypes.INTEGER,
            references: {
                model: 'Book_Tours',
                key: 'BookTourId'
            },
            onDelete: 'CASCADE'
        },
        UserId: {
            type: DataTypes.INTEGER,
            references: {
                model: 'Payments',
                key: 'UserId'
            },
            onDelete: 'CASCADE'
        },
        PaymentStatus: {
            type: DataTypes.BOOLEAN,
            defaultValue: false
        },
        PaymentDate: {
            type: DataTypes.DATE
        }
    }, {
        sequelize,
        modelName: 'Payment',
        tableName: 'Payments', // Tên bảng trong DB
        timestamps: true  // Nếu không cần createdAt, updatedAt
    });

    return Payment;
};

