sourcesContent:
'use strict';
const { Model } = require('sequelize');

module.exports = (sequelize, DataTypes) => {
    class Book_Tour extends Model {
        static associate(models) {
            Book_Tour.belongsTo(models.Tour, { foreignKey: "TourId", onDelete: "CASCADE" });
            Book_Tour.hasOne(models.Payment, { foreignKey: "BookTourId", onDelete: "CASCADE" });
        }
    }

    Book_Tour.init({
        BookTourId: {
            allowNull: false,
            autoIncrement: true,
            primaryKey: true,
            type: DataTypes.INTEGER
        },
        TourId: {
            type: DataTypes.INTEGER,
            references: {
                model: 'Tours',
                key: 'TourId'
            },
            onDelete: 'CASCADE'
        },
        QuantityAdults: {
            type: DataTypes.INTEGER,
            defaultValue: 0
        },
        QuantityChildren: {
            type: DataTypes.INTEGER,
            defaultValue: 0
        }
    }, {
        sequelize,
        modelName: 'Book_Tour',
        tableName: 'Book_Tours', // Tên bảng trong DB
        timestamps: true  // Nếu không cần createdAt, updatedAt
    });

    return Book_Tour;
};

