sourcesContent:
import db from "../models/index.js"

let createNewTest = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            await db.Test.create({
                TestId: data.TestId,
                TestName: data.TestName,
                TestAge: data.TestAge,
                TestAdd: data.TestAdd,
            })

            resolve({
                errCode: 0,
                message: 'OK'
            })
        } catch (e) {
            console.error("Error creating user:", e);
            reject(e);
        }
    })
}

let getAllTests = async (TestId) => {
    try {
        let tests;

        if (TestId === 'ALL') {
            tests = await db.Test.findAll(); // Lấy toàn bộ test
        } else {
            tests = await db.Test.findAll({
                where: { TestId: TestId }
            }); // Lấy tất cả test theo ID (dùng findAll thay vì findOne)
        }

        return tests;
    } catch (error) {
        throw new Error(error.message);
    }
};


export default {
    createNewTest,
    getAllTests,
};

