sourcesContent:
import db from "../models/index.js";

let getAllTours = (tourId) => {
    return new Promise(async (resolve, reject) => {
        try {
            let tours = [];
            if (tourId === 'ALL') {
                tours = await db.Tour.findAll();
            } else if (tourId) {
                tours = await db.Tour.findOne({
                    where: { TourId: tourId }
                });
            }

            if (!tours || tours.length === 0) {
                return reject({ errCode: 1, errMessage: "No tours found" });
            }

            resolve(tours);
        } catch (e) {
            reject(e);
        }
    });
};

let createNewTour = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!['Easy', 'Medium', 'High'].includes(data.TourDifficulty)) {
                return reject({
                    errCode: 1,
                    errMessage: "Invalid TourDifficulty value"
                });
            }

            await db.Tour.create(data);
            resolve({
                errCode: 0,
                message: "Tour created successfully!"
            });
        } catch (e) {
            reject(e);
        }
    });
};

let updateTourData = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.TourId) {
                return resolve({
                    errCode: 2,
                    errMessage: "Missing required parameter"
                });
            }

            let tour = await db.Tour.findOne({
                where: { TourId: data.TourId },
                raw: false,  // Chỉ định rằng chúng ta cần trả về instance để có thể gọi phương thức update
            });

            if (tour) {
                if (data.TourDifficulty && !['Easy', 'Medium', 'High'].includes(data.TourDifficulty)) {
                    return resolve({
                        errCode: 1,
                        errMessage: "Invalid TourDifficulty value"
                    });
                }

                if (data.TourName) tour.TourName = data.TourName;
                if (data.CategoryName) tour.CategoryName = data.CategoryName;
                if (data.TourLocation) tour.TourLocation = data.TourLocation;
                if (data.TourTime) tour.TourTime = data.TourTime;
                if (data.TourPrice) tour.TourPrice = data.TourPrice;
                if (data.TourDifficulty) tour.TourDifficulty = data.TourDifficulty;
                if (data.TourMinAge) tour.TourMinAge = data.TourMinAge;
                if (data.DescribeTour) tour.DescribeTour = data.DescribeTour;

                await tour.save();

                resolve({
                    errCode: 0,
                    message: "Tour updated successfully!"
                });
            } else {
                resolve({
                    errCode: 1,
                    errMessage: "Tour not found!"
                });
            }
        } catch (e) {
            reject({
                errCode: 500,
                errMessage: "Internal server error",
                error: e.message
            });
        }
    });
};

let deleteTour = (tourId) => {
    return new Promise(async (resolve, reject) => {
        try {
            let tour = await db.Tour.findOne({
                where: { TourId: tourId }
            });
            if (!tour) {
                return reject({
                    errCode: 2,
                    errMessage: "Tour does not exist"
                });
            }
            await db.Tour.destroy({
                where: { TourId: tourId }
            });
            resolve({
                errCode: 0,
                message: "Tour deleted successfully!"
            });
        } catch (e) {
            reject(e);
        }
    });
};

let searchTours = (query) => {
    return new Promise(async (resolve, reject) => {
        try {
            let filters = {};
            if (query.TourName) filters.TourName = { [db.Sequelize.Op.like]: `%${query.TourName}%` };
            if (query.CategoryName) filters.CategoryName = { [db.Sequelize.Op.like]: `%${query.CategoryName}%` };
            if (query.TourLocation) filters.TourLocation = { [db.Sequelize.Op.like]: `%${query.TourLocation}%` };
            if (query.TourPrice) filters.TourPrice = { [db.Sequelize.Op.lte]: query.TourPrice };
            if (query.TourDifficulty) filters.TourDifficulty = query.TourDifficulty;
            if (query.TourMinAge) filters.TourMinAge = { [db.Sequelize.Op.gte]: query.TourMinAge };

            let tours = await db.Tour.findAll({ where: filters });
            resolve(tours);
        } catch (e) {
            reject(e);
        }
    });
};

export default {
    getAllTours,
    createNewTour,
    updateTourData,
    deleteTour,
    searchTours,
};

