import paymentService from "../services/paymentService.js";

let handleGetAllPayments = async (req, res) => {
    try {
        let paymentId = req.query.id || "ALL"; // Lấy tất cả nếu không có id
        let payments = await paymentService.getAllPayments(paymentId);
        return res.status(200).json(payments);
    } catch (error) {
        return res.status(error.errCode || 500).json({
            errCode: error.errCode || 500,
            errMessage: error.errMessage || "Internal server error",
        });
    }
};

let handleCreateNewPayment = async (req, res) => {
    try {
        let response = await paymentService.createNewPayment(req.body);
        return res.status(200).json(response);
    } catch (error) {
        return res.status(error.errCode || 500).json(error);
    }
};

let handleUpdatePayment = async (req, res) => {
    try {
        let response = await paymentService.updatePayment(req.body);
        return res.status(200).json(response);
    } catch (error) {
        return res.status(error.errCode || 500).json(error);
    }
};

let handleDeletePayment = async (req, res) => {
    try {
        let response = await paymentService.deletePayment(req.body.PaymentId);
        return res.status(response.errCode === 0 ? 200 : 400).json(response);
    } catch (error) {
        return res.status(500).json({
            errCode: 500,
            errMessage: "Internal server error",
            error: error.message,
        });
    }
};

export default { handleGetAllPayments, handleCreateNewPayment, handleUpdatePayment, handleDeletePayment };

