sourcesContent:
import db from "@models/index.js";

let getAllBookTours = async (bookTourId) => {
    try {
        let bookTours = bookTourId === "ALL"
            ? await db.Book_Tour.findAll()
            : await db.Book_Tour.findOne({ where: { BookTourId: bookTourId } });

        if (!bookTours) {
            return { errCode: 1, errMessage: "No book tours found" };
        }
        return { errCode: 0, data: bookTours };
    } catch (error) {
        return { errCode: 500, errMessage: error.message };
    }
};

let createNewBookTour = async (data) => {
    try {
        if (!data.TourId || data.QuantityAdults < 0 || data.QuantityChildren < 0) {
            return { errCode: 1, errMessage: "Invalid input data" };
        }
        await db.Book_Tour.create(data);
        return { errCode: 0, message: "Book tour created successfully!" };
    } catch (error) {
        return { errCode: 500, errMessage: error.message };
    }
};

let updateBookTour = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.BookTourId) {
                return resolve({
                    errCode: 2,
                    errMessage: "Missing required parameter"
                });
            }

            let bookTour = await db.Book_Tour.findOne({
                where: { BookTourId: data.BookTourId },
                raw: false,
            });

            if (bookTour) {
                bookTour.TourId = data.TourId;
                bookTour.QuantityAdults = data.QuantityAdults;
                bookTour.QuantityChildren = data.QuantityChildren;
                await bookTour.save();

                resolve({
                    errCode: 0,
                    message: "Book tour updated successfully!"
                });
            } else {
                resolve({
                    errCode: 1,
                    errMessage: "Book tour not found!"
                });
            }
        } catch (e) {
            reject(e);
        }
    });
};

let deleteBookTour = async (bookTourId) => {
    try {
        let bookTour = await db.Book_Tour.findOne({ where: { BookTourId: bookTourId } });
        if (!bookTour) {
            return { errCode: 2, errMessage: "Book tour does not exist" };
        }
        await db.Book_Tour.destroy({ where: { BookTourId: bookTourId } });
        return { errCode: 0, message: "Book tour deleted successfully!" };
    } catch (error) {
        return { errCode: 500, errMessage: error.message };
    }
};

export default {
    getAllBookTours,
    createNewBookTour,
    updateBookTour,
    deleteBookTour
};

