sourcesContent:
import db from "@models/index.js";

let getAllDetails = async (detailId) => {
    try {
        let details = detailId === "ALL" ? await db.Detail.findAll() : await db.Detail.findOne({ where: { DetailId: detailId } });
        if (!details) {
            throw { errCode: 1, errMessage: "No details found" };
        }
        return details;
    } catch (e) {
        throw { errCode: 500, errMessage: "Database error", error: e.message };
    }
};

let createNewDetail = async (data) => {
    try {
        if (!data.TourId || !data.Des_Enjoy || !data.Des_Included) {
            throw { errCode: 1, errMessage: "Missing required parameters" };
        }
        await db.Detail.create(data);
        return { errCode: 0, message: "Detail created successfully!" };
    } catch (e) {
        throw { errCode: 500, errMessage: "Database error", error: e.message };
    }
};

let updateDetail = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.DetailId || typeof data.DetailId !== "string") {
                return resolve({
                    errCode: 2,
                    errMessage: "Missing or invalid DetailId",
                });
            }

            let detailId = data.DetailId.trim();
            let detail = await db.Detail.findOne({
                where: { DetailId: detailId },
                raw: false, 
            });

            if (detail) {
                const allowedFields = ["TourId", "Des_Enjoy", "Des_Included", "Des_Map", "Des_Itinerary"];
                allowedFields.forEach((key) => {
                    if (data[key] !== undefined) {
                        detail[key] = data[key];
                    }
                });

                await detail.save();
                resolve({
                    errCode: 0,
                    message: "Detail updated successfully!",
                });
            } else {
                resolve({
                    errCode: 1,
                    message: "Detail not found!",
                });
            }
        } catch (e) {
            reject({
                errCode: 500,
                errMessage: "Database error",
                errorDetail: e.message,
            });
        }
    });
};

let deleteDetail = async (detailId) => {
    try {
        let detail = await db.Detail.findOne({ where: { DetailId: detailId } });
        if (!detail) {
            return { errCode: 2, errMessage: "Detail does not exist" };
        }
        await db.Detail.destroy({ where: { DetailId: detailId } });
        return { errCode: 0, message: "Detail deleted successfully!" };
    } catch (error) {
        return { errCode: 500, errMessage: error.message };
    }
};

export default { getAllDetails, createNewDetail, updateDetail, deleteDetail };

