sourcesContent:
import db from "@models/index.js";

let getAllPayments = (paymentId) => {
    return new Promise(async (resolve, reject) => {
        try {
            let payments = [];
            if (paymentId === "ALL") {
                payments = await db.Payment.findAll();
            } else if (paymentId) {
                payments = await db.Payment.findOne({
                    where: { PaymentId: paymentId }
                });
            }

            if (!payments || payments.length === 0) {
                return reject({ errCode: 1, errMessage: "No payments found" });
            }

            resolve(payments);
        } catch (e) {
            reject(e);
        }
    });
};

let createNewPayment = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.BookTourId || !data.UserId || data.PaymentStatus === undefined) {
                return reject({
                    errCode: 1,
                    errMessage: "Missing required fields"
                });
            }

            await db.Payment.create({
                BookTourId: data.BookTourId,
                UserId: data.UserId,
                PaymentStatus: data.PaymentStatus,
                PaymentDate: data.PaymentDate || new Date()
            });

            resolve({
                errCode: 0,
                message: "Payment created successfully!"
            });
        } catch (e) {
            reject(e);
        }
    });
};

let updatePayment = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.PaymentId) {
                return resolve({
                    errCode: 2,
                    errMessage: "Missing required parameter"
                });
            }

            let payment = await db.Payment.findOne({
                where: { PaymentId: data.PaymentId },
                raw: false
            });

            if (payment) {
                payment.PaymentStatus = data.PaymentStatus;
                payment.PaymentDate = data.PaymentDate;

                await payment.save();
                resolve({
                    errCode: 0,
                    message: "Payment updated successfully!"
                });
            } else {
                resolve({
                    errCode: 1,
                    errMessage: "Payment not found!"
                });
            }
        } catch (e) {
            reject(e);
        }
    });
};

let deletePayment = async (paymentId) => {
    try {
        let payment = await db.Payment.findOne({ where: { PaymentId: paymentId } });
        if (!payment) {
            return { errCode: 2, errMessage: "Payment does not exist" };
        }
        await db.Payment.destroy({ where: { PaymentId: paymentId } });
        return { errCode: 0, message: "Payment deleted successfully!" };
    } catch (e) {
        return { errCode: 500, errMessage: "Database error", error: e.message };
    }
};

export default {
    getAllPayments,
    createNewPayment,
    updatePayment,
    deletePayment
};

