sourcesContent:
import express from 'express';
import userController from "@controllers/userController.js";
import tourController from '@controllers/tourController.js';
import detailController from "@controllers/detailController.js";
import testController from "@controllers/testController.js";
import bookTourController from '@controllers/bookTourController.js';
import paymentController from '@controllers/paymentController.js';
import auth from '@middleware/auth';


const router = express.Router();

let initWebRoutes = (app) => {
    router.post('/create-new-test', testController.handleCreateNewTest)
    router.get('/get-all-test', testController.handleGetAllTests)

    router.post('/login', userController.handleLogin);
    router.get('/get-all-users', userController.handleGetAllUsers);
    router.post('/create-new-user', userController.handleCreateNewUser);
    router.put('/update-user', userController.handleUpdateUser);
    router.delete('/delete-user', userController.handleDeleteUser);
    router.get("/forgot-password", userController.forgotPassword);
    router.post("/reset-password", userController.resetPassword);

    router.get('/get-all-tours', tourController.handleGetAllTours);
    router.post('/create-new-tour', tourController.handleCreateNewTour);
    router.put('/update-tour', tourController.handleUpdateTour);
    router.delete('/delete-tour', tourController.handleDeleteTour);
    router.get('/search-tour', tourController.handleSearchTours);

    router.get('/get-all-detail', detailController.handleGetAllDetails);
    router.post('/create-new-detail', detailController.handleCreateNewDetail);
    router.put('/update-detail', detailController.handleUpdateDetail);
    router.delete('/delete-detail', detailController.handleDeleteDetail);

    router.get('/get-all-booktours', bookTourController.handleGetAllBookTours);
    router.post('/create-new-booktour', bookTourController.handleCreateNewBookTour);
    router.put('/update-booktour', bookTourController.handleUpdateBookTour);
    router.delete('/delete-booktour', bookTourController.handleDeleteBookTour);

    router.get('/get-all-payments', paymentController.handleGetAllPayments);
    router.post('/create-new-payment', paymentController.handleCreateNewPayment);
    router.put('/update-payment', paymentController.handleUpdatePayment);
    router.delete('/delete-payment', paymentController.handleDeletePayment);

    return app.use("/", router);
};

export default initWebRoutes;

