'use strict';
const { Model } = require('sequelize');

module.exports = (sequelize, DataTypes) => {
    class Detail extends Model {
        static associate(models) {
            Detail.belongsTo(models.Tour, { foreignKey: "TourId", onDelete: "CASCADE" });
        }
    }

    Detail.init({
        DetailId: {
            allowNull: false,
            autoIncrement: true,
            primaryKey: true,
            type: DataTypes.INTEGER
        },
        TourId: {
            type: DataTypes.INTEGER,
            references: {
                model: 'Tours',
                key: 'TourId'
            },
            onDelete: 'CASCADE'
        },
        Des_Enjoy: DataTypes.TEXT,
        Des_Included: DataTypes.TEXT,
        Des_Map: DataTypes.TEXT,
        Des_Itinerary: DataTypes.TEXT
    }, {
        sequelize,
        modelName: 'Detail',
        tableName: 'Details', 
        timestamps: true 
    });

    return Detail;
};

