sourcesContent:
'use strict';
const { Model } = require('sequelize');

module.exports = (sequelize, DataTypes) => {
    class Payment extends Model {
        static associate(models) {
            Payment.belongsTo(models.Book_Tour, { foreignKey: "BookTourId", onDelete: "CASCADE" });
            Payment.belongsTo(models.User, { foreignKey: "UserId", onDelete: "CASCADE" });
        }
    }

    Payment.init({
        PaymentId: {
            allowNull: false,
            autoIncrement: true,
            primaryKey: true,
            type: DataTypes.INTEGER
        },
        BookTourId: {
            type: DataTypes.INTEGER,
            references: {
                model: 'Book_Tours',
                key: 'BookTourId'
            },
            onDelete: 'CASCADE'
        },
        UserId: {
            type: DataTypes.INTEGER,
            references: {
                model: 'Users',
                key: 'UserId'
            },
            onDelete: 'CASCADE'
        },
        PaymentMethod: {
            type: DataTypes.STRING,
        },
        TransactionId: {
            type: DataTypes.STRING,
        },
        Amount: {
            type: DataTypes.FLOAT,
        },
        PaymentStatus: {
            type: DataTypes.BOOLEAN,
            defaultValue: false
        },
    }, {
        sequelize,
        modelName: 'Payment',
        tableName: 'Payments',
        timestamps: true
    });

    return Payment;
};

