sourcesContent:
import db from "@models/index.js"

let createNewTest = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            await db.Test.create({
                TestId: data.TestId,
                TestName: data.TestName,
                TestAge: data.TestAge,
                TestAdd: data.TestAdd,
            })

            resolve({
                errCode: 0,
                message: 'OK'
            })
        } catch (e) {
            console.error("Error creating test:", e);
            reject(e);
        }
    })
}

let getAllTests = async (TestId) => {
    try {
        let tests;

        if (TestId === 'ALL') {
            tests = await db.Test.findAll();
        } else {
            tests = await db.Test.findAll({
                where: { TestId: TestId }
            });
        }

        return tests;
    } catch (error) {
        throw new Error(error.message);
    }
};

let updateTest = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.TestId) {
                return resolve({
                    errCode: 2,
                    errMessage: "Missing required parameter"
                });
            }
            let test = await db.Test.findOne({
                where: { TestId: data.TestId },
                raw: false,
            });
            if (test) {
                test.TestName = data.TestName;
                test.TestAge = data.TestAge;
                test.TestAdd = data.TestAdd;
                await test.save();
                resolve({
                    errCode: 0,
                    message: "Test updated successfully!"
                });
            } else {
                resolve({
                    errCode: 1,
                    message: "Test not found!"
                });
            }
        } catch (e) {
            reject(e);
        }
    });
};

let deleteTest = (testId) => {
    return new Promise(async (resolve, reject) => {
        try {
            let test = await db.Test.findOne({ where: { TestId: testId } });
            if (!test) {
                return resolve({
                    errCode: 2,
                    errMessage: "Test does not exist"
                });
            }
            await db.Test.destroy({ where: { TestId: testId } });
            resolve({
                errCode: 0,
                message: "Test deleted successfully!"
            });
        } catch (e) {
            reject(e);
        }
    });
};

export default {
    createNewTest,
    getAllTests,
    updateTest,
    deleteTest
};

