'use strict';
require('dotenv').config();

const fs = require('fs');
const path = require('path');
const mongoose = require('mongoose');
const basename = path.basename(__filename);
const db = {};

// 1️⃣. Kết nối MongoDB
const MONGO_URI = process.env.MONGO_URI || 'mongodb://127.0.0.1:27017/travel_db';

mongoose.connect(MONGO_URI, {
    useNewUrlParser: true,
    useUnifiedTopology: true
});

const connection = mongoose.connection;
connection.on('connected', () => {
    console.log('MongoDB connected 🚀');
});

connection.on('error', (err) => {
    console.error('MongoDB connection error:', err.message);
});

// 2️⃣. Tự động load tất cả các model trong folder này
fs
    .readdirSync(__dirname)
    .filter(file => {
        return (
            file.indexOf('.') !== 0 && // không lấy file ẩn
            file !== basename &&       // không lấy chính file index.js
            file.slice(-3) === '.js'   // chỉ lấy các file .js
        );
    })
    .forEach(file => {
        const model = require(path.join(__dirname, file))(mongoose);
        db[model.modelName] = model; // Lưu model vào object db
    });

// 3️⃣. Export db và mongoose connection nếu cần
db.mongoose = mongoose;
db.connection = connection;

module.exports = db;

