sourcesContent:
import mongoose from 'mongoose';
import dotenv from 'dotenv';
dotenv.config();

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/travel_web_db';

// Kết nối MongoDB
mongoose.connect(MONGO_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
}).then(() => {
  console.log('MongoDB connected');
}).catch(err => {
  console.error('MongoDB connection error:', err);
});

// Import từng seed
import seedTests from './seeds/seed-tests.js';
import seedUsers from './seeds/seed-users.js';
import seedTours from './seeds/seed-tours.js';
import seedDetails from './seeds/seed-details.js';
import seedBookTours from './seeds/seed-book-tours.js';
import seedPayments from './seeds/seed-payments.js';

const runSeeds = async () => {
  try {
    await seedTests();
    await seedUsers();
    await seedTours();
    await seedDetails();
    await seedBookTours();
    await seedPayments();

    console.log('✅ All seeds done!');
  } catch (err) {
    console.error('❌ Seeding error:', err);
  } finally {
    mongoose.connection.close();
  }
};

runSeeds();

