sourcesContent:
import mongoose from 'mongoose';
import dotenv from 'dotenv';
dotenv.config();

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/travel_web_db';

// Kết nối MongoDB
mongoose.connect(MONGO_URI, {
    useNewUrlParser: true,
    useUnifiedTopology: true,
});

// Định nghĩa Schema và Model
const testSchema = new mongoose.Schema({
    TestId: Number,
    TestName: String,
    TestAge: String,
    TestAdd: String,
});

const Test = mongoose.model('Test', testSchema);

// Data mẫu
const testData = [
    { TestId: 1, TestName: 'Nguyễn Văn A', TestAge: '25', TestAdd: 'Hà Nội' },
    { TestId: 2, TestName: 'Trần Thị B', TestAge: '30', TestAdd: 'Hải Phòng' },
    { TestId: 3, TestName: 'Lê Văn C', TestAge: '28', TestAdd: 'Đà Nẵng' },
];

// Hàm seed
const seedTests = async () => {
    try {
        await Test.deleteMany(); // Xóa toàn bộ data cũ
        console.log('Old data cleared!');

        await Test.insertMany(testData); // Thêm data mới
        console.log('Seed completed!');

        mongoose.connection.close(); // Đóng kết nối sau khi seed
    } catch (err) {
        console.error('Seed failed:', err);
    }
};

seedTests();

