sourcesContent:
import mongoose from 'mongoose';
import Tour from '@models/tourModel.js';

async function seedTours() {
  await mongoose.connect('mongodb://localhost:27017/tours_db');

  const tours = [
    {
      TourName: 'Ha Long Bay Adventure',
      CategoryName: 'Nature',
      TourLocation: 'Ha Long',
      TourTime: 3,
      TourPrice: 1000000,
      TourDifficulty: 'Easy',
      TourMinAge: 12,
      DescribeTour: 'A wonderful trip to Ha Long Bay.',
    },
    {
      TourName: 'Phong Nha Cave',
      CategoryName: 'Nature',
      TourLocation: 'Quang Binh',
      TourTime: 5,
      TourPrice: 2000000,
      TourDifficulty: 'Medium',
      TourMinAge: 20,
      DescribeTour: 'A wonderful trip to Quang Binh.',
    }
  ];

  await Tour.insertMany(tours);
  console.log('Seeded tours!');
  mongoose.disconnect();
}

seedTours();

