sourcesContent:
import mongoose from "mongoose";
import Detail from "@models/detailModel.js";

const seedDetails = async () => {
    try {
        await mongoose.connect("mongodb://localhost:27017/your_database_name");

        const details = [
            {
                TourId: new mongoose.Types.ObjectId("605c5fcf8f1b2c349c0edcc5"), // Thay bằng ObjectId thực tế
                Des_Enjoy: 'Beautiful nature',
                Des_Included: 'Hotel, Food, Guide',
                Des_Map: 'Map URL',
                Des_Itinerary: 'Day 1: Visit caves... Day 2: Cruise...'
            },
            {
                TourId: new mongoose.Types.ObjectId("605c5fcf8f1b2c349c0edcc6"),
                Des_Enjoy: 'Beautiful caves',
                Des_Included: 'Hotel, Food, Guide',
                Des_Map: 'Map URL',
                Des_Itinerary: 'Day 1: Visit caves... Day 2: Cruise...'
            }
        ];

        await Detail.insertMany(details);
        console.log("Seeding details completed!");
        process.exit();
    } catch (err) {
        console.error(err);
        process.exit(1);
    }
};

seedDetails();

