sourcesContent:
import mongoose from 'mongoose';
import BookTour from '@models/bookTourModel.js';

mongoose.connect('mongodb://localhost:27017/yourdbname', {
    useNewUrlParser: true,
    useUnifiedTopology: true
});

const seedBookTours = async () => {
    try {
        await BookTour.deleteMany({}); // Clear existing
        await BookTour.insertMany([
            {
                TourId: new mongoose.Types.ObjectId(), // giả lập ObjectId
                QuantityAdults: 2,
                QuantityChildren: 1
            },
            {
                TourId: new mongoose.Types.ObjectId(),
                QuantityAdults: 10,
                QuantityChildren: 0
            }
        ]);
        console.log('Seed completed!');
        process.exit();
    } catch (error) {
        console.error(error);
        process.exit(1);
    }
};

seedBookTours();

