sourcesContent:
import User from '@models/userModel.js';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import nodemailer from 'nodemailer';
import dotenv from 'dotenv';

dotenv.config();

const saltRounds = 10;
const secretKey = process.env.SECRET_KEY;
const tokenExpiry = process.env.TOKEN_EXPIRY;

const hashUserPassword = async (password) => {
    if (!password) {
        throw new Error('Mật khẩu không được để trống!');
    }
    return bcrypt.hash(password, saltRounds);
};

const handleUserLogin = async (email, password) => {
    try {
        const user = await User.findOne({ Email: email }).lean();

        if (!user) {
            return { errCode: 1, errMessage: 'Email không tồn tại.' };
        }

        const checkPassword = await bcrypt.compare(password, user.UserPassword);
        if (!checkPassword) {
            return { errCode: 3, errMessage: 'Mật khẩu không đúng.' };
        }

        const token = jwt.sign(
            { email: user.Email, role: user.Role },
            secretKey,
            { expiresIn: tokenExpiry }
        );

        delete user.UserPassword;

        return {
            errCode: 0,
            errMessage: 'Đăng nhập thành công!',
            user,
            token
        };
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const checkUserEmail = async (email) => {
    try {
        const user = await User.findOne({ Email: email });
        return !!user;
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const getAllUsers = async () => {
    try {
        const users = await User.find({}, '-UserPassword').lean();
        return users;
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const getUserById = async (userId) => {
    try {
        const user = await User.findById(userId, '-UserPassword').lean();
        return user;
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const createNewUser = async (data) => {
    try {
        const { Email, UserName, UserPassword, Phone, Role } = data;

        const existingUser = await User.findOne({ Email });
        if (existingUser) {
            return { errCode: 1, errMessage: 'Email đã được sử dụng.' };
        }

        const hashedPassword = await hashUserPassword(UserPassword);

        const newUser = new User({
            UserName,
            UserPassword: hashedPassword,
            Email,
            Phone,
            Role: Role || 'user'
        });

        await newUser.save();

        return { errCode: 0, message: 'Tạo tài khoản thành công!' };
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const updateUserData = async (data) => {
    try {
        const { UserId, UserName, Email, Phone, Role } = data;

        if (!UserId) {
            return { errCode: 1, errMessage: 'Thiếu tham số UserId!' };
        }

        const user = await User.findById(UserId);
        if (!user) {
            return { errCode: 2, errMessage: 'Không tìm thấy user!' };
        }

        user.UserName = UserName || user.UserName;
        user.Email = Email || user.Email;
        user.Phone = Phone || user.Phone;
        user.Role = Role || user.Role;

        await user.save();

        return { errCode: 0, message: 'Cập nhật thông tin thành công!' };
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const deleteUser = async (userId) => {
    try {
        const user = await User.findByIdAndDelete(userId);
        if (!user) {
            return { errCode: 1, errMessage: 'Không tìm thấy user!' };
        }

        return { errCode: 0, message: 'Xoá user thành công!' };
    } catch (error) {
        console.error(error);
        throw error;
    }
};

const sendResetPasswordEmail = async (email) => {
    try {
        const user = await User.findOne({ Email: email });
        if (!user) {
            return { errCode: 1, errMessage: 'Email không tồn tại trong hệ thống!' };
        }

        const token = jwt.sign({ email: user.Email }, secretKey, { expiresIn: '15m' });
        const resetLink = `http://localhost:3000/reset-password?token=${token}`;

        const testAccount = await nodemailer.createTestAccount();

        const transporter = nodemailer.createTransport({
            host: 'smtp.ethereal.email',
            port: 587,
            secure: false,
            auth: {
                user: testAccount.user,
                pass: testAccount.pass
            }
        });

        const info = await transporter.sendMail({
            from: '"Your App" <no-reply@example.com>',
            to: email,
            subject: 'Yêu cầu đặt lại mật khẩu',
            text: `Nhấn vào link sau để đặt lại mật khẩu: ${resetLink}`,
            html: `<p>Bạn đã yêu cầu đặt lại mật khẩu. Nhấn vào <a href="${resetLink}">đây</a> để tiếp tục.</p>`
        });

        console.log('Xem email tại:', nodemailer.getTestMessageUrl(info));

        return {
            errCode: 0,
            message: 'Email hướng dẫn đặt lại mật khẩu đã được gửi!',
            previewURL: nodemailer.getTestMessageUrl(info)
        };
    } catch (error) {
        console.error('Lỗi khi gửi email reset password:', error);
        return { errCode: 2, errMessage: 'Lỗi hệ thống!', error: error.message };
    }
};

const resetPassword = async (token, newPassword) => {
    try {
        const decoded = jwt.verify(token, secretKey);

        const user = await User.findOne({ Email: decoded.email });
        if (!user) {
            return { errCode: 1, errMessage: 'Không tìm thấy user!' };
        }

        user.UserPassword = await hashUserPassword(newPassword);
        await user.save();

        return { errCode: 0, message: 'Mật khẩu đã được cập nhật!' };
    } catch (error) {
        console.error('Lỗi reset mật khẩu:', error);
        return { errCode: 2, errMessage: 'Lỗi hệ thống!' };
    }
};

export default {
    handleUserLogin,
    checkUserEmail,
    getAllUsers,
    getUserById,
    createNewUser,
    updateUserData,
    deleteUser,
    sendResetPasswordEmail,
    resetPassword
};

